  fn: (client: TaxKitApiClient) => Effect.Effect<A, E, R>
): Effect.Effect<A, E, R | TaxKitHttpApiService> =>
  Effect.gen(function* () {
    const client = yield* TaxKitHttpApiService;
    return yield* fn(client);
  });
