import { Content } from "@common-practice/content/service";
import { ApiRoutes } from "@common-practice/http/server";
import { applyResponsePolicy, requestPathname } from "@common-practice/http/publishing-policy";
import { mcpRoutes } from "@common-practice/mcp/server";
import { isPublicMcpOrigin } from "@common-practice/mcp/schemas";
import { RpcRoutes } from "@common-practice/rpc/server";
import * as Boolean from "effect/Boolean";
import * as Context from "effect/Context";
import * as Deferred from "effect/Deferred";
import * as Effect from "effect/Effect";
import * as ErrorReporter from "effect/ErrorReporter";
import * as Layer from "effect/Layer";
import * as Option from "effect/Option";
import type * as Scope from "effect/Scope";
import * as HttpEffect from "effect/http/HttpEffect";
import * as Headers from "effect/http/Headers";
import * as HttpRouter from "effect/http/HttpRouter";
import * as HttpServerError from "effect/http/HttpServerError";
import * as HttpServerRequest from "effect/http/HttpServerRequest";
import * as HttpServerResponse from "effect/http/HttpServerResponse";
import { publishingRoutes } from "../aeo/routes.egress";
import { agentSkillsRoutes } from "../aeo/agent-skills.egress";

export class ApiHandler extends Context.Service<
  ApiHandler,
  {
    readonly http: Effect.Effect<
      HttpServerResponse.HttpServerResponse,
      never,
      HttpServerRequest.HttpServerRequest | Scope.Scope
    >;
  }
>()("common-practice/ApiHandler") {}

// All native transports call Content. They share its isolate lifetime, while each
// incoming request keeps its own fibre, cancellation signal and response scope.
export const apiHandlerLayer = Layer.effect(
  ApiHandler,
  Effect.gen(function* () {
    const routes = Layer.mergeAll(
      ApiRoutes,
      RpcRoutes,
      mcpRoutes,
      publishingRoutes,
      agentSkillsRoutes,
      HttpRouter.cors({
        allowedOrigins: ["*"],
        allowedMethods: ["GET", "HEAD", "POST", "OPTIONS"],
        allowedHeaders: [
          "content-type",
          "accept",
          // Native Effect clients propagate both tracing formats in browsers.
          "b3",
          "traceparent",
          "mcp-protocol-version",
          "mcp-method",
          "mcp-name",
        ],
        exposedHeaders: ["mcp-protocol-version"],
        credentials: false,
        maxAge: 300,
      }),
    );
    const router = yield* HttpRouter.toHttpEffect(routes);
    const services = Context.pick(Content)(yield* Effect.context<Content>());
    const http = Effect.gen(function* () {
      const request = yield* HttpServerRequest.HttpServerRequest;
      const originHeader = Headers.get(request.headers, "origin");
      // Validate Origin before CORS, including OPTIONS preflight requests.
      const response = yield* Boolean.match(
        Option.exists(originHeader, (value) => !isPublicMcpOrigin(value)),
        {
          onTrue: () => Effect.succeed(HttpServerResponse.empty({ status: 403 })),
          onFalse: () =>
            router.pipe(
              Effect.catchCause((cause) =>
                HttpServerError.causeResponse(cause).pipe(
                  Effect.flatMap(([recovered, reportable]) =>
                    ErrorReporter.report(reportable).pipe(Effect.as(recovered)),
                  ),
                ),
              ),
            ),
        },
      );
      return applyResponsePolicy({
        request: {
          adapter: "machine",
          method: request.method,
          pathname: requestPathname(request),
        },
        response,
      });
    }).pipe(Effect.provideContext(services));
    return ApiHandler.of({ http });
  }),
);

export const serveResponse = Effect.fnUntraced(function* (
  request: HttpServerRequest.HttpServerRequest,
) {
  const { http } = yield* ApiHandler;
  const served = yield* Deferred.make<HttpServerResponse.HttpServerResponse>();
  yield* HttpEffect.toHandled(http, (handled, response) =>
    Deferred.succeed(
      served,
      Boolean.match(HttpServerResponse.omitsBody(response, handled.method === "HEAD"), {
        onFalse: () => HttpEffect.scopeTransferToStream(response),
        onTrue: () => response,
      }),
    ),
  ).pipe(Effect.provideService(HttpServerRequest.HttpServerRequest, request));
  return yield* Deferred.await(served);
});

export const webResponse = Effect.fn("Api.webResponse")(function* (request: Request) {
  const serverRequest = HttpServerRequest.fromWeb(request);
  const response = yield* serveResponse(serverRequest);
  const context = yield* Effect.context();
  return HttpServerResponse.toWeb(response, { withoutBody: request.method === "HEAD", context });
});
