import * as Result from "effect/Result";
import * as Schema from "effect/Schema";
import * as Url from "effect/http/Url";

const HttpUrl = Schema.URLFromString.check(
  Schema.makeFilter(
    (url) =>
      (url.protocol === "https:" || url.protocol === "http:") &&
      url.username === "" &&
      url.password === "" &&
      url.origin.length <= 2048,
  ),
);

// Native URL validation supplies the checked representation of a browser origin.
export const McpOrigin = HttpUrl.check(
  Schema.makeFilter((url) => url.pathname === "/" && url.search === "" && url.hash === ""),
).pipe(Schema.brand("McpOrigin"));
export type McpOrigin = typeof McpOrigin.Type;
const isMcpOriginUrl = Schema.is(McpOrigin);

// The native MCP callback is synchronous. Preserve the exact header text because
// URL parsing normalises addresses and adds a slash.
export const isPublicMcpOrigin = (input: string) =>
