import {
  ContentUnavailableError,
  InvalidContentResponseError,
} from "@common-practice/content/errors";
import { checkedPageOperation } from "@common-practice/content/response-check";
import { Content, contentClientTimeout } from "@common-practice/content/service";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Match from "effect/Match";
import type * as HttpClientError from "effect/http/HttpClientError";
import * as HttpApiClient from "effect/http-api/HttpApiClient";
import { ContentApi } from "./api";
import { HttpApiAddress } from "./config";

const httpFailure = (
  operation: "get-page" | "list-pages",
  error: HttpClientError.HttpClientError,
) =>
  Match.value(error.reason).pipe(
    Match.tag("DecodeError", () => new InvalidContentResponseError({ operation })),
    Match.tag("EmptyBodyError", () => new InvalidContentResponseError({ operation })),
    Match.orElse(() => new ContentUnavailableError({ operation })),
  );

export const contentHttpClientLayer = Layer.effect(
  Content,
  Effect.gen(function* () {
    const options = yield* HttpApiAddress;
    const client = yield* HttpApiClient.make(ContentApi, options);
    return Content.of({
      listPages: client.pages.listPages({}).pipe(
        Effect.timeoutOrElse({
          duration: contentClientTimeout,
          orElse: () => Effect.fail(new ContentUnavailableError({ operation: "list-pages" })),
        }),
        Effect.catchTags({
          HttpClientError: (error) => Effect.fail(httpFailure("list-pages", error)),
          SchemaError: () =>
            Effect.fail(new InvalidContentResponseError({ operation: "list-pages" })),
        }),
        Effect.withSpan("Content.listPages"),
      ),
      getPage: checkedPageOperation({
        getPage: (request) =>
          client.pages
            .getPage({
              params: { id: request.id },
              query: { format: request.format },
            })
            .pipe(
              Effect.timeoutOrElse({
                duration: contentClientTimeout,
                orElse: () => Effect.fail(new ContentUnavailableError({ operation: "get-page" })),
              }),
              Effect.catchTags({
                HttpClientError: (error) => Effect.fail(httpFailure("get-page", error)),
                SchemaError: () =>
                  Effect.fail(new InvalidContentResponseError({ operation: "get-page" })),
              }),
            ),
      }),
    });
  }),
);
