// visit; Cloudflare may reuse the same Worker version's response for seven days.
export const publicPageCacheControl = "public, max-age=0";
export const publicDiscoveryCacheControl = "public, max-age=300";
export const publicCdnCacheControl = "public, max-age=604800, stale-if-error=0";
export const noStoreCacheControl = "no-store";
