/**
 * The host adapter that produced a response. Page responses come from TanStack or
 * Accept negotiation: they vary on Accept and may be public 307 redirects.
 */
type ResponsePolicyAdapter = "machine" | "page";

/** Facts the host adapter already has for one request. */
export interface ResponsePolicyRequest {
  readonly adapter: ResponsePolicyAdapter;
  readonly method: string;
  readonly pathname: Option.Option<string>;
  /** The Website supplies this from its checked stage; false blocks search indexing. */
  readonly indexable?: boolean;
  /** The host read visitor-specific state for this response. */
  readonly privateResponse?: boolean;
  /** HTML cache lookups must distinguish the request's Cookie header. */
  readonly varyCookie?: boolean;
}

/** Facts read from one response, using Effect's case-insensitive Headers. */
export interface ResponsePolicyFacts extends ResponsePolicyRequest {
  readonly status: number;
  readonly headers: Headers.Headers;
  readonly cookies: Cookies.Cookies;
}

const mergeVary = (vary: Option.Option<string>, header: string): string =>
  Option.match(vary, {
    onNone: () => header,
    onSome: (value) => {
      if (value.trim() === "") {
        return header;
      }
      const includesHeader = Array.some<string>(
        (part) => part.trim().toLowerCase() === header.toLowerCase(),
      )(value.split(","));
      return Boolean.match(includesHeader, {
        onFalse: () => `${value}, ${header}`,
        onTrue: () => value,
      });
    },
  });

const includesContentType = (contentType: Option.Option<string>, value: string): boolean =>
  Option.match(contentType, {
    onNone: () => false,
    onSome: (contentTypeValue) => contentTypeValue.toLowerCase().includes(value),
  });

const isReadMethod = (method: string): boolean => method === "GET" || method === "HEAD";

/**
 * Build the shared cache and safety headers. This is a total function over facts the
 * host adapter has already read, so it adds no span or failure to each request.
 */
export const responsePolicyHeaders = (
  facts: ResponsePolicyFacts,
): Readonly<Record<string, string>> => {
  const contentType = Headers.get(facts.headers, "content-type");
  const cacheControl = Headers.get(facts.headers, "cache-control");
  const cdnCacheControl = Headers.get(facts.headers, "cdn-cache-control");
  const cloudflareCacheControl = Headers.get(facts.headers, "cloudflare-cdn-cache-control");
  const declaredControls = Array.getSomes([cacheControl, cdnCacheControl, cloudflareCacheControl]);
