import type { ContentApi } from "@common-practice/http/api";
import type { PageFormat, PageRequest, PageResponse } from "@common-practice/content/schemas";
import type { CourseRequest } from "@common-practice/training/schemas";
import { contentClientTimeout } from "@common-practice/content/service";
import { trainingClientTimeout } from "@common-practice/training/service";
import { InvalidContentResponseError } from "@common-practice/content/errors";
import { InvalidTrainingResponseError } from "@common-practice/training/errors";
import * as Effect from "effect/Effect";
import type * as HttpApiClient from "effect/http-api/HttpApiClient";

export type WebsiteHttpClient = HttpApiClient.ForApi<typeof ContentApi>;

// HttpApiClient validates the union. These checks relate the reply to its request.
export const requestPage = Effect.fn("Website.requestPage")(
  <const Format extends PageFormat>({
    client,
    input,
  }: Readonly<{
    client: WebsiteHttpClient;
    input: PageRequest & Readonly<{ format: Format }>;
  }>) =>
    client.pages
      .getPage({
        params: { id: input.id },
        query: { format: input.format },
      })
      .pipe(
        Effect.timeout(contentClientTimeout),
        Effect.filterOrFail(
          (response): response is Extract<PageResponse, { readonly format: Format }> =>
            response.format === input.format,
          () => new InvalidContentResponseError({ operation: "get-page" }),
        ),
      ),
);

export const requestCourse = Effect.fn("Website.requestCourse")(function* ({
  client,
  input,
}: Readonly<{ client: WebsiteHttpClient; input: CourseRequest }>) {
  const course = yield* client.courses
    .getCourse({ params: input })
    .pipe(Effect.timeout(trainingClientTimeout));
  if (course.id !== input.id) {
    return yield* new InvalidTrainingResponseError({ operation: "get-course" });
  }
  return course;
});
